# Corrige el dashboard para que use Rent Commencement Date del lease como respaldo
# cuando no hay Rent Schedule capturado (Center Plazas, Centro Las Americas, Coacalco,
# La Paz Puebla). Bosque Urbano e Izazaga seguiran en blanco a proposito (TBD en Leasecake).
# Ejecuta esto parado en la raiz del repo.

$ErrorActionPreference = 'Stop'

# --- backend/src/routes/arrendamientos/dashboard.js ---
$f1b64 = ""
$dir = Split-Path -Parent "backend\src\routes\arrendamientos\dashboard.js"
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes((Resolve-Path ".").Path + "\backend\src\routes\arrendamientos\dashboard.js", [System.Convert]::FromBase64String($f1b64))

Write-Host "Listo: dashboard.js corregido."
git add backend/src/routes/arrendamientos/dashboard.js
git commit -m "Dashboard: usar rent_commencement_date como respaldo si falta el Rent Schedule"
git push origin main